// Director's Cut: audio asset naming + pure ambience-mix maths (Agent H).
// Shared by UDCAudioSubsystem and the audio automation tests. Assets are generated by Tools/audio_gen.py.
#pragma once

#include "CoreMinimal.h"
#include "UObject/SoftObjectPath.h"
#include "Core/DCAudioSubsystem.h"
#include "Core/DCAssetPaths.h"

/** Test-only access to UDCAudioSubsystem's private event queue (defined in DCAudioSubsystem.cpp). */
struct FDCAudioTestAccess
{
	static int32 QueuedCount(const UDCAudioSubsystem* A, FName Sfx);
	static void ClearQueue(UDCAudioSubsystem* A);
};

namespace DCAudio
{
	/** Every canonical SFX name (DCSfx::*). */
	inline const TArray<FName>& AllSfxNames()
	{
		static const TArray<FName> Names = {
			DCSfx::Click, DCSfx::Hover, DCSfx::PanelOpen, DCSfx::PanelClose, DCSfx::Confirm, DCSfx::Error,
			DCSfx::Cash, DCSfx::SlotFill, DCSfx::MissionStart, DCSfx::MissionComplete, DCSfx::Success, DCSfx::Fail,
			DCSfx::Busted, DCSfx::LevelUp, DCSfx::BuildStart, DCSfx::RoomBuilt, DCSfx::Perk, DCSfx::Payday,
			DCSfx::GarageDoor, DCSfx::CarDepart, DCSfx::CarArrive };
		return Names;
	}

	inline FSoftObjectPath MakePath(const FString& AssetName)
	{
		return FSoftObjectPath(FString::Printf(TEXT("%s/%s.%s"), DCPaths::AudioRoot, *AssetName, *AssetName));
	}

	/** Number of round-robin variants (SFX_<Name>, SFX_<Name>_2, ...). */
	inline int32 SfxVariantCount(FName Name)
	{
		if (Name == DCSfx::Click) { return 3; }
		if (Name == DCSfx::Hover) { return 2; }
		return 1;
	}

	/** Variant 0 = SFX_<Name>; variant N>0 = SFX_<Name>_<N+1>. */
	inline FString SfxAssetName(FName Name, int32 Variant = 0)
	{
		return Variant <= 0 ? TEXT("SFX_") + Name.ToString() : FString::Printf(TEXT("SFX_%s_%d"), *Name.ToString(), Variant + 1);
	}
	inline FSoftObjectPath SfxPath(FName Name, int32 Variant = 0) { return MakePath(SfxAssetName(Name, Variant)); }

	/** Looping ambience beds, crossfaded continuously. */
	enum EBed : int32 { BedInterior = 0, BedCityDay, BedCityNight, BedRain, BedCount };
	inline const TCHAR* BedAssetName(int32 Bed)
	{
		static const TCHAR* Names[BedCount] = { TEXT("AMB_Interior"), TEXT("AMB_CityDay"), TEXT("AMB_CityNight"), TEXT("AMB_Rain") };
		return Names[FMath::Clamp(Bed, 0, (int32)BedCount - 1)];
	}

	/** Random distant one-shots (stereo, distance baked in). */
	inline const TArray<FString>& DayOneShots()   { static const TArray<FString> N = { TEXT("AMB_Construction"), TEXT("AMB_CarPass") }; return N; }
	inline const TArray<FString>& NightOneShots() { static const TArray<FString> N = { TEXT("AMB_Siren"), TEXT("AMB_DogBark"), TEXT("AMB_TrainHorn"), TEXT("AMB_CarPass") }; return N; }

	/** Every asset that must exist under /Game/DC/Audio. */
	inline TArray<FString> AllAssetNames()
	{
		TArray<FString> Out;
		for (const FName& N : AllSfxNames())
		{
			for (int32 V = 0; V < SfxVariantCount(N); ++V) { Out.Add(SfxAssetName(N, V)); }
		}
		for (int32 B = 0; B < BedCount; ++B) { Out.Add(BedAssetName(B)); }
		for (const FString& S : DayOneShots()) { Out.AddUnique(S); }
		for (const FString& S : NightOneShots()) { Out.AddUnique(S); }
		return Out;
	}

	/** v1 assets that must be gone (music + theatre sounds). Anything MUS_* is also forbidden. */
	inline const TArray<FString>& ObsoleteAssetNames()
	{
		static const TArray<FString> N = {
			TEXT("SFX_Clapper"), TEXT("SFX_Typewriter"), TEXT("SFX_Typewriter_2"), TEXT("SFX_Typewriter_3"), TEXT("SFX_Stamp"),
			TEXT("SFX_DiceRoll"), TEXT("SFX_Commit"), TEXT("SFX_CounterTick"), TEXT("SFX_StingWrap"), TEXT("SFX_StingCut"),
			TEXT("SFX_StingLevelUp"), TEXT("SFX_StingRoom"), TEXT("SFX_StingPerk"), TEXT("AMB_Projector"), TEXT("AMB_Neon") };
		return N;
	}

	// ── Ambience mix (pure; unit-tested) ─────────────────────────────────────

	/** 0 at night .. 1 in full day, from the clock hour (dawn ramp 05:00-08:00, dusk ramp 18:30-21:00). */
	inline float DayFactor(float Hour)
	{
		const float H = FMath::Fmod(FMath::Fmod(Hour, 24.f) + 24.f, 24.f);
		auto Smooth = [](float A, float B, float X) { const float T = FMath::Clamp((X - A) / (B - A), 0.f, 1.f); return T * T * (3.f - 2.f * T); };
		return H < 12.f ? Smooth(5.f, 8.f, H) : 1.f - Smooth(18.5f, 21.f, H);
	}

	inline uint32 Hash2(int32 A, int32 B)
	{
		uint32 H = (uint32)A * 0x9E3779B1u ^ ((uint32)B + 0x7F4A7C15u + ((uint32)A << 6) + ((uint32)A >> 2));
		H ^= H >> 16; H *= 0x85EBCA6Bu; H ^= H >> 13; H *= 0xC2B2AE35u; H ^= H >> 16;
		return H;
	}

	/** Some days rain (never day 1). Deterministic from the run seed. */
	inline bool IsRainyDay(int32 Seed, int32 Day) { return Day >= 2 && (Hash2(Seed, Day) % 100u) < 28u; }

	/** 0..1 rain intensity at Hour on Day: a 4-10 h shower starting at a seeded hour, with 1 h ramps. */
	inline float RainAmount(int32 Seed, int32 Day, float Hour)
	{
		if (!IsRainyDay(Seed, Day)) { return 0.f; }
		const uint32 H = Hash2(Seed ^ 0x5A17, Day);
		const float Start = (float)(H % 15u) + 1.f;          // 01:00 .. 15:00
		const float Len = 4.f + (float)((H >> 8) % 7u);       // 4 .. 10 h
		const float In = FMath::Clamp(Hour - Start, 0.f, 1.f);
		const float Out = FMath::Clamp(Start + Len - Hour, 0.f, 1.f);
		return FMath::Min(In, Out);
	}

	struct FAmbienceMix { float Bed[BedCount] = { 0.f, 0.f, 0.f, 0.f }; };

	/** Target linear gains (before the Master/Ambience channel volumes) for each bed. */
	inline FAmbienceMix ComputeAmbienceMix(bool bActiveRun, float Hour, float Rain, bool bPaused)
	{
		FAmbienceMix M;
		if (!bActiveRun)
		{
			// Title: the empty warehouse at night, low.
			M.Bed[BedInterior] = 0.9f;
			M.Bed[BedCityNight] = 0.45f;
			return M;
		}
		const float D = DayFactor(Hour);
		const float R = FMath::Clamp(Rain, 0.f, 1.f);
		const float Under = 1.f - 0.35f * R;                  // rain masks the city
		M.Bed[BedInterior] = 0.9f;
		M.Bed[BedCityDay] = FMath::Sin(D * UE_HALF_PI) * Under;
		M.Bed[BedCityNight] = FMath::Cos(D * UE_HALF_PI) * Under;
		M.Bed[BedRain] = 0.9f * R;
		if (bPaused)
		{
			for (float& G : M.Bed) { G *= 0.55f; }
		}
		return M;
	}
}
